sys_variable_value.value:
(function execute(inputs, outputs) {

var inputsPayload = {};
inputsPayload['note_days_to_factor'] = inputs.days_to_factor;
inputsPayload['incident_sysid'] = inputs.inc_sys_id;

var capabilityId = '1ea955de2ba6661024d5f3d0de91bf04'; 
var request = {
	executionRequests: [{
		payload: inputsPayload,
		capabilityId: capabilityId,
		meta: {
			skillConfigId: '26a91dde2ba6661024d5f3d0de91bf19'
		}
	}], 
	mode: 'sync' 
};

try {
	var response = sn_one_extend.OneExtendUtil.execute(request) || {}; 
	var skillResponse = ((response["capabilities"] || {})[capabilityId] || {})["response"]; 
	//outputs.results = JSON.stringify(skillResponse);
	outputs.results = JSON.parse(skillResponse).model_output;
} catch(e) {
	gs.error(e);
	gs.addErrorMessage('Something went wrong while executing skill.');
}
//action.setRedirectURL(current);
})(inputs, outputs);

